// CSD_RATIONALE_BEGIN
// Root-cause analysis of attempt 26 regression (14.3%):
//   1. Manual CloseSpanIfComplete+ConstrainedStep loop exits on EOS mid-expression,
//      leaving 9 spans unterminated; phase-2 CloseSpanWithinBudget then has steps==maxSteps
//      so its guard fails and the span never closes.
//   2. Model emits multiple intermediate <<>> spans; last extracted span is a partial result.
//   3. Guidance allowed model to write {n} template references in reasoning.
//
// Best known result: attempt 24 (GenerateWithPrefixAndManagedSpan, 78% prefix, 34.7%).
// This attempt builds on that but changes:
//   a. prefixBudget = 85% (765/900) — more free reasoning, still 135 steps for span.
//   b. Stronger guidance: "Do NOT use << >> mid-reasoning; write ONE final <<expr>> only."
//      This discourages the model from emitting early intermediate spans so that:
//      - The first natural << is the final answer span.
//      - The forced open at step 765 is more likely the final expression.
//      - The LAST closed span (which the evaluator extracts) is the complete formula.
//   c. Higher boostAmount (10.0) to keep parser-valid tokens strongly preferred inside spans.
//
// GenerateWithPrefixAndManagedSpan handles all span lifecycle concerns
// (open on <<, close when complete, force-open at prefixBudget, budget accounting)
// so we avoid all the manual-loop edge cases that caused the regression.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Initialization copies the precondition-valid inputs unchanged.
//   GenerateWithPrefixAndManagedSpan's postcondition directly guarantees:
//     !insideConstrainedOut ==> currentConstrainedOut == []  AND
//     insideConstrainedOut  ==> parser.IsValidPrefix(currentConstrainedOut)
//   so no additional proof effort is required after the single helper call.
//
// progress: |generated| <= |generatedPrefix| + maxSteps, cost <= maxSteps
//   Initialization: generated == generatedPrefix, cost == 0, so |generated| - |generatedPrefix| = 0 <= maxSteps. ✓
//   After the helper: its postcondition guarantees |generated| <= |generatedPrefix| + maxSteps.
//   We set cost := maxSteps, so cost <= maxSteps. ✓
//   Liveness postcondition: maxSteps == 0 takes the first branch (cost = 0, and precondition
//   rules that branch correct); maxSteps > 0 enters the else branch and sets cost = maxSteps > 0,
//   satisfying "cost > 0". ✓
//   Visible growth is bounded because every token appended to generated inside the helper
//   consumes one step from the total maxSteps budget; EOS and parser-rejected suffix tokens
//   count against the budget without growing visible output, so |generated| growth <= maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve the math problem step by step using plain text reasoning only. " +
    "Do NOT write << >> during intermediate steps. " +
    "After completing all reasoning, write your FINAL answer EXACTLY ONCE as <<expr>>. " +
    "Inside <<expr>>: variable names without braces (write n not {n}, mult not {mult}, frac_1 not {frac_1}), " +
    "numbers, and operators: +, -, *, /, //, %, (, ), int(). " +
    "Use // for integer division. Wrap the COMPLETE combined formula (all variables combined). " +
    "Examples: <<n * (mult + 1)>>, <<int(t * frac1 + (total - t) * frac2)>>, <<int(length / (plant_width + space) - owned) * cost>>. " +
    "ONE <<expr>> at the very end. No LaTeX, no {braces}, no **, no intermediate <<>> spans.");

  var prefixBudget: nat := (maxSteps * 85) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt,
    generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 10.0, 6, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

